SELECT ?film ?filmLabel ?director ?directorLabel ?deathDate ?deathYear WHERE {
  VALUES ?film { dbr:Notes_on_the_Port_of_St._Francis dbr:De_Luxe_Annie }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:deathDate ?deathDate . BIND(YEAR(?deathDate) AS ?deathYearFromDate) }
